// Renders every coolshapes shape (with its grain) to a static SVG file in
// public/shapes/, and writes the list of identifiers to src/shapes/list.ts.
// Run by hand (`npm run export-shapes`) after upgrading coolshapes-react; the
// generated files are committed. The app never imports coolshapes-react: the
// package holds all shapes in one module that cannot be tree-shaken.
import { copyFileSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
// The CommonJS entry point does not expose named exports under Node: use the ESM build.
import { Coolshape, shapes } from "coolshapes-react/dist/esm/coolshapes.js";

const outDir = new URL("../public/shapes/", import.meta.url);
rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });

const ids = [];
for (const [family, list] of Object.entries(shapes)) {
  list.forEach((_, index) => {
    const id = `${family}-${index + 1}`;
    const svg = renderToStaticMarkup(
      createElement(Coolshape, { type: family, index, noise: true }),
    );
    writeFileSync(new URL(`${id}.svg`, outDir), svg + "\n");
    ids.push(id);
  });
}
copyFileSync(
  new URL("../node_modules/coolshapes-react/LICENSE", import.meta.url),
  new URL("LICENSE", outDir),
);

const families = Object.keys(shapes);
writeFileSync(
  new URL("../src/shapes/list.ts", import.meta.url),
  `// Generated by scripts/export-shapes.mjs from coolshapes-react (MIT). Do not edit.\n\n` +
    `export const shapeFamilies = ${JSON.stringify(families)} as const;\n\n` +
    `export const shapeIds: readonly string[] = ${JSON.stringify(ids)};\n`,
);
console.log(`${ids.length} shapes exported`);
